import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { useTranslation } from 'react-i18next';
import { useScrollStore } from '@/stores/useScrollStore';

export function LabTelemetry() {
  const frames = useRef(0);
  const start = useRef(0);
  const { t } = useTranslation('lab');
  useFrame(() => {
    const progress = document.getElementById('lab-progress');
    if (progress) progress.value = useScrollStore.getState().scrollProgress;
    frames.current++;
    const now = performance.now();
    if (!start.current) start.current = now;
    if (now - start.current >= 500) {
      const output = document.getElementById('lab-fps');
      if (output) output.textContent = t('fpsValue', { value: Math.round(frames.current * 1000 / (now - start.current)) });
      frames.current = 0;
      start.current = now;
    }
  });
  return null;
}

