import { BackSide } from 'three';
import { useScrollStore } from '@/stores/useScrollStore';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { useSectionAnchor } from '@/3d/hooks/useSectionAnchor';

function PlanetModel({ anchor, frozen, quality }) {
  const root = useSectionAnchor(anchor, 1.8, frozen);
  const segments = quality === 'low' ? 24 : 40;

  return (
    <group ref={root} name="about-planet" visible={false}>
      <ambientLight color="#FFFFFF" intensity={0.25} />
      <pointLight color="#FFFFFF" position={[-3, 2, 3]} intensity={35} distance={16} />
      <mesh name="planet-surface">
        <sphereGeometry args={[1, segments, segments / 2]} />
        <meshStandardMaterial color="#111111" roughness={0.85} metalness={0} />
      </mesh>
      {/* A thin back-face shell gives a white rim without a shader or bloom pass. */}
      <mesh name="planet-rim" scale={1.015}>
        <sphereGeometry args={[1, segments, segments / 2]} />
        <meshBasicMaterial color="#FFFFFF" side={BackSide} toneMapped={false} />
      </mesh>
