import { Suspense, useSyncExternalStore } from 'react';
import { Canvas } from '@react-three/fiber';
import { Selection } from '@react-three/postprocessing';
import { SceneBoundary } from '@/3d/components/SceneBoundary';
import { SceneFallback } from '@/3d/components/SceneFallback';
import { useMediaQuery } from '@/3d/hooks/useMediaQuery';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { StarField } from '@/3d/components/StarField';
import { ShootingStars } from '@/3d/components/ShootingStars';
import { FloatingObjects } from '@/3d/components/FloatingObjects';
import { Nebula } from '@/3d/components/Nebula';
import { BlackHoleSystem } from '@/3d/components/BlackHoleSystem';
import { CameraRig } from '@/3d/components/CameraRig';
import { QUALITY } from '@/3d/quality';
import { INITIAL_CAMERA_POSITION } from '@/3d/utils/cameraPath';
import { useScrollStore } from '@/stores/useScrollStore';

function subscribeToVisibility(notify) {
  document.addEventListener('visibilitychange', notify);
  return () => document.removeEventListener('visibilitychange', notify);
}

function isHidden() {
  return typeof document !== 'undefined' && document.hidden;
}

export function GalaxyScene({ children, count, quality: chosenQuality, rayQuality, enableBloom = true }) {
  const sectionPieceActive = useScrollStore((state) => ['about', 'skills'].includes(state.currentSection));
  const hidden = useSyncExternalStore(subscribeToVisibility, isHidden, () => false);
  const frozen = useReducedMotion();
  const mobile = useMediaQuery('(max-width: 767px)');
  const tablet = useMediaQuery('(max-width: 1023px)');
  const quality = chosenQuality ?? rayQuality ?? (mobile ? 'low' : tablet ? 'medium' : 'high');

  return (
    <div className="fixed inset-0 z-0 pointer-events-none bg-background" data-galaxy-scene data-quality={quality}>
      <SceneBoundary>
        <Canvas
          className="pointer-events-none!"
          aria-hidden="true"
          camera={{ position: INITIAL_CAMERA_POSITION, fov: 60, near: 0.1, far: 400 }}
          dpr={mobile ? 1 : [1, 1.75]}
          gl={{ antialias: false, powerPreference: 'high-performance' }}
          frameloop={hidden ? 'never' : 'always'}
          fallback={<SceneFallback />}
        >
          <color attach="background" args={['#050505']} />
          <Suspense fallback={null}>
            <Selection>
              <CameraRig frozen={frozen} />
              <StarField count={count ?? QUALITY[quality]} frozen={frozen} />
              <Nebula position={[0, 0, -240]} scale={[80, 40, 1]} colorA="#202020" colorB="#4A4A4A" frozen={frozen} />
              <Nebula position={[-16, 5, -270]} scale={[50, 30, 1]} colorA="#262626" colorB="#5A5A5A" frozen={frozen} />
              {/* Section pieces replace the full-screen ray image and stay bloom-free. */}
              {!sectionPieceActive && <BlackHoleSystem frozen={frozen} quality={quality} enableBloom={enableBloom} />}
              {!hidden && <FloatingObjects frozen={frozen} />}
              {!hidden && !frozen && <ShootingStars />}
              {typeof children === 'function' ? children(quality) : children}
            </Selection>
          </Suspense>
        </Canvas>
      </SceneBoundary>
    </div>
  );
}

